<div class="detail-grid">
    <div class="detail-grid__main">
        <section class="card panel-card"><div class="panel-card__head"><div><div class="panel-title">Module Content</div><p class="panel-card__sub">Student-facing orientation material.</p></div><span class="badge <?= e(status_class($module['status'])) ?>"><?= e($module['status']) ?></span></div><?php if (!empty($module['description'])): ?><p class="content-lede"><?= e($module['description']) ?></p><?php endif; ?><?php if ($objectives !== []): ?><div class="objective-list"><div class="section-title">Learning Objectives</div><ul><?php foreach ($objectives as $objective): ?><li><?= App\Support\Icons::render('check', 13) ?> <?= e($objective) ?></li><?php endforeach; ?></ul></div><?php endif; ?><div class="content-detail"><?= body_html($module['body']) ?></div><?php if ($mediaFile !== null): ?><div class="attachment-list attachment-list--rows"><div class="file-row"><span class="file-row__icon"><?= App\Support\Icons::render('fileText', 18) ?></span><div class="file-row__body"><div class="cell-title"><?= e($mediaFile['original_name'] ?? 'Module media') ?></div><div class="cell-sub"><?= e(format_bytes((int) ($mediaFile['size_bytes'] ?? 0))) ?> &middot; <?= e($module['content_type']) ?></div></div><a class="btn btn--ghost btn--sm" href="<?= url('/admin/orientation/' . $module['public_id'] . '/media') ?>"><?= App\Support\Icons::render('download', 13) ?> Download</a></div></div><?php endif; ?></section>
