        <section class="card panel-card"><div class="panel-card__head"><div class="panel-title">Recent Activity</div><a class="link" href="<?= url('/admin/activity') ?>">View all</a></div><div class="mini-list"><?php foreach (array_slice($audit ?? [], 0, 6) as $entry): ?><div class="mini-item"><span class="log-item__ico"><?= App\Support\Icons::render($entry['icon'] ?? 'info', 13) ?></span><div><strong><?= e($entry['title']) ?></strong><span><?= e($entry['text']) ?></span></div><em><?= e(time_ago($entry['created_at'])) ?></em></div><?php endforeach; ?></div></section>
